262: /// required to change one string into the other.
263: ///
264: /// ```
265: /// use strsim::levenshtein;
266: ///
267: /// assert_eq!(3, levenshtein("kitten", "sitting"));
268: /// ```
269: pub fn levenshtein(a: &str, b: &str) -> usize {
